// Generated by scripts/sync-v4.mjs from the Cadente v4 prototype. Do not edit.
// Projeção pura: estado → HTML. Um desenho por tipo de linha; nenhum controle nativo.
import { activeTab, focused, findLeaf, rects, visualTabs, sideItems, jumpLabels, linesOf, overlayResults, completions, ctxOf, activityOf, activities, STATES } from './model.mjs';
import { plugin } from './plugins.mjs';
import { hintFor, KEYMAP } from './keys.mjs';
import { viewsOf } from './engine.mjs';
import { PROCS } from './data.mjs';
import { nextEvent } from './life.mjs';

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const tone = t => t ? ` ${t}` : '';
const SPARK = '▁▂▃▄▅▆▇█';
const ALERT = { 'aprovar?': 'warn', falhou: 'err' };
// Estado de atividade (como no Orca): spinner trabalhando, ? precisa de você, ✓ pronto (apagado depois de visto), ● falhou.
const ST = { 'precisa de você': ['?', 'warn'], falhou: ['●', 'err'], trabalhando: ['', 'spin'], pronto: ['✓', 'ok'] };
const TONE = { 'precisa de você': 'warn', falhou: 'err', trabalhando: '', pronto: 'ok' };
const sg = a => `<i class="g st ${ST[a.state][1]}${a.state === 'pronto' && !a.unread ? ' read' : ''}" title="${a.state}">${ST[a.state][0]}</i>`;
// Resumo de várias folhas (aba, pasta): um glifo por estado presente, com a contagem, do mais urgente ao mais calmo.
const chips = acts => STATES.map(st => [st, acts.filter(a => a.state === st)]).filter(([, xs]) => xs.length)
  .map(([st, xs]) => `<span class="chip">${sg({ state: st, unread: xs.some(a => a.unread) })}${xs.length}</span>`).join('');
const kbd = (action, S) => { const k = hintFor(action, S); return k ? `<span class="kbd">${k}</span>` : ''; };
const ln = (cls, g, text, meta, attrs = '') => `<div class="ln ${cls}"${attrs}><i class="g">${g ?? ''}</i><span class="tx">${text}</span>${meta ? `<span class="mt">${meta}</span>` : ''}</div>`;

function line(l, cur) {
  const c = cur ? ' data-cursor' : '';
  switch (l.t) {
    case 'h': return `<div class="ln h"${c}><span class="tx">${esc(l.text)}</span>${l.meta ? `<span class="mt">${esc(l.meta)}</span>` : ''}</div>`;
    case 'row': {
      const stat = l.stat ? `<span class="st"><b class="ok">+${l.stat[0]}</b> <b class="err">−${l.stat[1]}</b></span>` : '';
      const g = `<i class="g${l.tone && l.g === '●' ? tone(l.tone) : ''}">${esc(l.g)}</i>`;
      return `<div class="ln row${l.tone === 'dim' ? ' dim' : ''}"${c}>${g}<span class="tx">${esc(l.text)}</span>${stat}<span class="mt">${esc(l.meta)}</span></div>`;
    }
    case 'blk': return `<div class="blk${l.ok === false ? ' fail' : ''}"${c}>${ln('cmd', esc(l.g ?? '$'), esc(l.cmd), esc(l.meta))}${l.out.map(o => typeof o === 'string' ? ln('out', '', esc(o)) : ln(`out${tone(o.tone)}`, '', esc(o.text))).join('')}</div>`;
    case 'diff': return `<div class="ln diff${l.sign === '+' ? ' add' : l.sign === '-' ? ' del' : ''}"${c}><i class="no">${l.o ?? ''}</i><i class="no">${l.n ?? ''}</i><i class="sg">${l.sign.trim()}</i><span class="tx">${esc(l.code)}</span></div>`;
    case 'note': return ln(`note${tone(l.tone)}`, esc(l.g), esc(l.text), '', c);
    case 'bar': return `<div class="ln bar${tone(l.tone)}"${c}><span class="lb">${esc(l.label)}</span><span class="track"><i style="width:${Math.max(0, Math.min(100, l.pct))}%"></i></span><span class="mt">${esc(l.meta)}</span></div>`;
    case 'spark': {
      const max = Math.max(...l.values), min = Math.min(...l.values);
      const chars = l.values.map(v => SPARK[Math.round(((v - min) / (max - min || 1)) * 7)]).join('');
      return `<div class="ln spark"${c}><span class="lb">${esc(l.label)}</span><span class="sk">${chars}</span><span class="mt">${esc(l.meta)}</span></div>`;
    }
    case 'msg': return ln(`msg ${l.who}`, l.who === 'agent' ? '<span class="sr">Cadente: </span>◆' : '<span class="sr">Você: </span>›', esc(l.text), '', c);
    case 'ask': return ln('ask', '●', esc(l.text), '', c) + ln('note keys', '', esc(l.keys));
    case 'hr': return '<div class="hr"></div>';
    case 'tui': return l.html;
    default: return '';
  }
}

const PICKS = {
  acts: ov => [`ações · ${ov.title}`, 'tecla ou ↑↓ ↵ · esc', x => `<b class="kbd">${esc(x.key)}</b>`],
  choose: ov => [ov.title, '↑↓ ↵ · esc', () => '·'],
  history: () => ['buscar no histórico', '↑↓ ↵ · esc', () => '$'],
};

function content(S, leaf, isFocused) {
  const ov = S.overlay;
  // Seletores dentro da folha (ações do item, escolha, histórico): cabeçalho, linhas e dica de teclas iguais.
  const pick = PICKS[ov?.kind === 'pick' ? ov.mode : ov?.kind]?.(ov);
  if (pick && ov.pane === leaf.id) return `<div class="pick">${ln('h', '', esc(pick[0]), pick[1])}${overlayResults(S).map((x, i) => ln('row', pick[2](x), esc(x.label), '', ` data-sel="${i === ov.sel}"`)).join('')}</div>`;
  if (ov?.kind === 'mention' && ov.pane === leaf.id) {
    const items = overlayResults(S);
    return `<div class="pick">${ln('h', '', `anexos · ${ov.filter} · ${ov.scope}${ov.picked.length ? ` · ${ov.picked.length} selecionados` : ''}`, '⇥ tipo · ←→ recentes · espaço marca · ↵ insere')}${items.map((a, i) => ln('row', ov.picked.includes(a.slug) ? '●' : '○', `@${esc(a.slug)}`, esc(a.type), ` data-sel="${i === ov.sel}"`)).join('') || ln('note dim', '', 'nenhum anexo')}${ln('note dim', '', '⌘C copia slug · ⌘↵ Finder · ⌘⌫ exclui')}</div>`;
  }
  const views = viewsOf(leaf.plugin, leaf);
  const at = Math.max(0, views.findIndex(v => v.id === (leaf.data.view === 'ficha' ? leaf.data.form?.back : leaf.data.view)));
  // Ordem fixa do manifesto (memória espacial); o app rola a faixa só para mostrar a vista ativa.
  const tabs = views.length > 1 ? `<div class="ln tabs">${leaf.data.view === 'ficha' ? '<span class="vt on">ficha</span>' : ''}<span class="vts">${views.map(v => `<span class="vt${v.id === leaf.data.view ? ' on' : ''}">${esc(v.label)}</span>`).join('')}</span><span class="mt">${at + 1}/${views.length} ⇥</span></div>` : '';
  if (ov?.kind === 'pick' && ov.mode === 'plugin' && ov.pane === leaf.id) {
    const rows = overlayResults(S).map((r, i) => `<div class="ln row" data-sel="${i === ov.sel}"><i class="g">${esc(plugin(r.plugin).glyph)}</i><span class="tx">${esc(r.label)}</span><span class="mt">${esc(plugin(r.plugin).keywords)}</span></div>`);
    return `<div class="pick">${rows.join('') || ln('note dim', '', 'nenhum plugin com esse nome')}</div>`;
  }
  let n = -1;
  return tabs + linesOf(leaf, S).map(l => line(l, l.id && ++n === leaf.cursor && isFocused !== null)).join('');
}

function prompt(S, leaf, isFocused, view) {
  const ov = S.overlay, p = plugin(leaf.plugin), c = ctxOf(leaf, S);
  const picking = ov?.kind === 'pick' && ov.mode === 'plugin' && ov.pane === leaf.id;
  const text = picking ? ov.query : leaf.input.text, caret = picking ? ov.query.length : leaf.input.caret;
  const parts = [];
  if (!picking && isFocused && leaf.input.text.startsWith('/')) {
    const list = completions(S, leaf).slice(0, 5);
    parts.push(`<div class="cmp">${list.map((x, i) => ln('row', '/', esc(x.name), esc(x.desc), i === leaf.input.sel ? ' data-sel="true"' : '')).join('')}</div>`);
  }
  if (isFocused && ov?.kind === 'confirm' && !S.ui.side) parts.push(ln('ask conf', '●', esc(ov.text), 'y confirmar · n cancelar'));
  if (isFocused && ov?.kind === 'capture') parts.push(ln('ask conf', '⌘', esc(ov.text), 'pressione o atalho · esc cancela'));
  const finding = ov?.kind === 'find' && ov.pane === leaf.id;
  const hits = finding && ov.query ? JSON.stringify(linesOf(leaf, S)).split('"').filter(x => x.includes(ov.query)).length : 0;
  const d = leaf.data, status = finding ? `buscar: ${ov.query || '…'} · ${hits} resultado${hits === 1 ? '' : 's'} · ↵ próximo · ⇧↵ anterior · esc` : picking ? 'abrir plugin nesta folha' : d.editing ? `editando ${d.editing.label} · ↵ grava · esc descarta` : d.busy ? `${d.busy.label}… · esc cancela` : view.status ?? '';
  parts.push(`<div class="ln ctx"><span class="cwd">${esc(c.cwd)}</span><span class="br"> ${esc(c.branch)}</span>${c.subject ? `<span class="sub">${leaf.link ? '⇢ ' : ''}${esc(c.subject)}</span>` : ''}${(pr => pr && !String(c.subject ?? '').includes(`#${pr.n}`) ? `<span class="sub">PR #${pr.n}</span>` : '')(S.store.prs?.find(x => x.branch === c.branch))}<span class="mt">${esc(status)}</span></div>`);
  const before = esc(text.slice(0, caret)), at = esc(text[caret] ?? ' '), after = esc(text.slice(caret + 1));
  // O aviso da última ação ocupa o lugar da dica no prompt da folha focada: é onde o olho está, e some na próxima tecla.
  const hint = !text && isFocused && S.ui.toast ? `<span class="hint toast">${esc(S.ui.toast)}</span>` : !text && leaf.data.suggest ? `<span class="hint">${esc(leaf.data.suggest)}  → aceita</span>` : !text ? `<span class="hint">${esc(picking ? 'nome do plugin' : leaf.data.commenting ? `comentar ${leaf.data.commenting.label}` : (typeof p?.hint === 'function' ? p.hint(leaf) : p?.hint) ?? '')}</span>` : '';
  const body = isFocused ? `${before}<b class="cur">${at}</b>${after}${hint}` : `${esc(text)}${hint}`;
  parts.push(`<div class="ln in${text.includes('\n') ? ' multi' : ''}" role="textbox" aria-label="Entrada de ${esc(p?.title ?? 'folha nova')}"><i class="g">›</i><span class="tx">${body}</span></div>`);
  return `<footer class="pp">${parts.join('')}</footer>`;
}

function pane(S, leaf, { focusedId, labels, inset, multi }) {
  const p = plugin(leaf.plugin), isFocused = leaf.id === focusedId && !S.ui.side && !['palette', 'name'].includes(S.overlay?.kind);
  const view = p ? p.view(leaf, S) : { lines: [] };
  const label = labels.find(l => l.leaf === leaf.id);
  const signal = p?.signal?.(leaf, S) ?? '';
  const act = activityOf(leaf, S), title = act?.title ? `${act.who} · ${act.title}` : p ? `${p.title}${view.subject ? ` · ${view.subject}` : ''}` : 'folha nova';
  const lead = label ? `<b class="jl" data-tab="${label.tab}" data-leaf="${leaf.id}">${label.label}</b>` : esc(p?.glyph ?? '+');
  return `<section class="pane" data-pane data-id="${leaf.id}" data-plugin="${leaf.plugin ?? ''}" data-view="${esc(leaf.data.view ?? '')}" data-focused="${leaf.id === focusedId}" data-dim="${S.ui.dim && (S.ui.side || (multi && leaf.id !== focusedId))}">`
    + `<header class="ph${inset ? ' inset' : ''}"><span class="pl">${lead}</span><span class="pt">${esc(title)}</span>${act ? `<span class="ps act">${sg(act)}<span class="${TONE[act.state]}">${esc([act.label, act.elapsed].filter(Boolean).join(' · '))}</span></span>` : `<span class="ps${tone(ALERT[signal])}">${esc(signal)}</span>`}</header>`
    + `<div class="pc">${content(S, leaf, isFocused)}</div>${prompt(S, leaf, isFocused, view)}</section>`;
}

function tree(S, node, ctx) {
  if (node.kind === 'leaf') return pane(S, node, { ...ctx, inset: !S.ui.sidebar && ctx.topLeft === node.id });
  const grow = r => `style="flex-grow:${r}"`;
  return `<div class="split ${node.axis}" ${grow(1)}><div class="cell" ${grow(node.ratio)}>${tree(S, node.a, ctx)}</div><div class="sp"></div><div class="cell" ${grow(1 - node.ratio)}>${tree(S, node.b, ctx)}</div></div>`;
}

function sidebar(S, labels) {
  const items = sideItems(S), order = visualTabs(S), fid = focused(S).id;
  const rows = items.map((it, i) => {
    const cur = S.ui.side && i === S.ui.sideCursor ? ' data-side-cursor' : '';
    const base = `data-side-item data-kind="${it.kind}" data-id="${it.id ?? ''}"${cur}`;
    if (it.kind === 'group') {
      const g = S.groups.find(x => x.id === it.id);
      const tabs = S.tabs.filter(t => t.group === g.id), acts = g.open ? [] : tabs.flatMap(t => leavesOf(t).map(l => activityOf(l, S)).filter(Boolean));
      return `<div class="ln si grp" ${base}><i class="g">${g.open ? '▾' : '▸'}</i><span class="tx">${esc(g.name)}</span><span class="mt${acts.length ? ' chips' : ''}">${acts.length ? chips(acts) : tabs.length}</span></div>`;
    }
    if (it.kind === 'tab') {
      const t = S.tabs.find(x => x.id === it.id), n = order.indexOf(t) + 1;
      const acts = leavesOf(t).map(l => activityOf(l, S)).filter(Boolean), alert = !acts.length && leavesOf(t).map(l => plugin(l.plugin)?.signal?.(l, S)).find(s => ALERT[s]);
      return `<div class="ln si tab${t.id === S.active ? ' on' : ''}" ${base} data-tab="${t.id}" data-n="${n}"><i class="g">${n <= 9 ? n : '·'}</i><span class="tx">${esc(t.title)}</span><span class="mt${acts.length ? ' chips' : tone(ALERT[alert])}">${acts.length ? chips(acts) : esc(alert || '')}</span></div>`;
    }
    if (it.kind === 'leaf') {
      const { leaf } = findLeaf(S, it.id), p = plugin(leaf.plugin), label = labels.find(l => l.leaf === leaf.id);
      const a = activityOf(leaf, S), sig = p?.signal?.(leaf, S) ?? '', subject = p?.view(leaf, S).subject;
      const g = label ? `<i class="g"><b class="jl" data-tab="${label.tab}" data-leaf="${leaf.id}">${label.label}</b></i>` : a ? sg(a) : `<i class="g">${esc(p?.glyph ?? '+')}</i>`;
      const name = a?.title ?? a?.who ?? (p ? [p.short ?? p.title, subject].filter(Boolean).join(' ') : 'nova');
      const meta = !a ? sig : a.state === 'trabalhando' && a.elapsed ? a.elapsed : ''; // o glifo diz o estado; o detalhe fica no cabeçalho e em ⌘⇧A
      return `<div class="ln si leaf${leaf.id === fid ? ' on' : ''}" ${base}>${g}<span class="tx">${esc(name)}</span><span class="mt${a ? ` act${tone(TONE[a.state])}` : tone(ALERT[sig])}">${esc(meta)}</span></div>`;
    }
    if (it.kind === 'windows') return `<div class="ln si grp" ${base}><i class="g">▾</i><span class="tx">janelas</span><span class="mt">${S.windows.length}</span></div>`;
    if (it.kind === 'grave-head') return `<div class="ln si grp grave-head" ${base}><i class="g">${S.ui.graveOpen ? '▾' : '▸'}</i><span class="tx">cemitério</span><span class="mt">${S.grave.length}</span></div>`;
    const g = S.grave.find(x => x.id === it.id);
    return `<div class="ln si grave" ${base}><i class="g">↺</i><span class="tx">${esc(g.title)}</span><span class="mt">${g.kind === 'tab' ? 'aba' : 'folha'}</span></div>`;
  });
  const ov = S.overlay;
  let foot = '';
  if (S.ui.side && ov?.kind === 'confirm') foot = ln('ask conf', '●', esc(ov.text), 'y · n');
  else if (ov?.kind === 'name') foot = ln('in', '›', `${esc(ov.query)}<b class="cur"> </b>`, ov.purpose === 'group' ? 'nova pasta' : 'renomear');
  else if (ov?.kind === 'pick' && ov.mode === 'group') foot = overlayResults(S).map((r, i) => ln('row', '·', esc(r.label), '', ` data-sel="${i === ov.sel}"`)).join('') + ln('in', '›', `${esc(ov.query)}<b class="cur"> </b>`, 'mover para');
  const hints = S.ui.side
    ? KEYMAP.filter(e => e.scope === 'sidebar' && /^[↵⌫mnr]$/.test(e.keys)).map(e => `<span class="hk"><span class="kbd">${e.keys}</span> ${e.label.split(' ')[0].toLowerCase()}</span>`).join('')
    : [[{ type: 'HELP' }, 'atalhos'], [{ type: 'PALETTE' }, 'comandos'], [{ type: 'JUMP' }, 'saltar'], [{ type: 'CHAT_BESIDE' }, 'chat']]
      .map(([a, t]) => `<span class="hk">${kbd(a, S)} ${t}</span>`).join('');
  return `<aside class="side" data-sidebar data-focus="${S.ui.side}"><div class="sh"><span class="tl"><i></i><i></i><i></i></span><span class="mark">◆</span></div>`
    + `<div class="sl">${rows.join('')}</div><div class="sf">${foot}${statusLines(S).map(t => `<div class="ln stl"><span class="tx">${esc(t)}</span></div>`).join('')}<div class="hints">${hints}</div></div></aside>`;
}
const leavesOf = t => { const walk = n => n.kind === 'leaf' ? [n] : [...walk(n.a), ...walk(n.b)]; return walk(t.tree); };

// Linha de estado: os widgets do Cadente (perfil, atividades, uso, memória, pomodoro, próximo evento, clima).
function statusLines(S) {
  const all = S.tabs.flatMap(t => leavesOf(t));
  const foco = all.find(l => l.plugin === 'foco' && l.data.running);
  const mb = PROCS.reduce((s, p) => s + p[1], 0) + (S.clock % 5);
  const next = nextEvent(S);
  const w = S.store.weather, acts = S.store.activities?.length ?? 0;
  const live = activities(S), need = live.filter(x => x.a.state === 'precisa de você').length, work = live.filter(x => x.a.state === 'trabalhando').length;
  const n = acts + live.length;
  return [`◆ ${S.store.profile?.name ?? 'pessoal'} · ${n} atividade${n === 1 ? '' : 's'}`, (need || work) && `${need ? `? ${need} aguarda${need > 1 ? 'm' : ''} você` : `${work} rodando`} · ⌘⇧A`, `uso ${S.store.usage?.session.pct ?? 0}% · mem ${mb} MB`,
    [foco && `◉ ${String(Math.floor(foco.data.left / 60)).padStart(2, '0')}:${String(foco.data.left % 60).padStart(2, '0')}`, w && `${w.temp}° ${w.cond}`].filter(Boolean).join(' · '),
    next && `◷ ${next.time} ${next.title}`].filter(Boolean);
}

function notice(S) {
  const n = S.notices[0];
  if (!n) return '';
  const keys = { backup: '↵ ok', importCli: 'y importar · n agora não', downgrade: 'r restaurar backup · c continuar' }[n.kind];
  return `<div class="ov" data-notice><div class="ln q"><i class="g">◆</i><span class="tx">${esc(n.title)}</span></div><div class="res">${n.lines.map(t => ln('note', '', esc(t))).join('')}${ln('ask', '●', esc(keys))}</div></div>`;
}

// Paleta (⌘P) e Atalhos (⌘/) usam a mesma janela central: busca, contagem e linhas com glifo, texto e tecla ou origem.
function central(S, hint, row, empty = 'nada encontrado') {
  const ov = S.overlay, results = overlayResults(S);
  let sec;
  const rows = results.flatMap((r, i) => [...(r.section && r.section !== sec ? [ln('h', '', esc(sec = r.section))] : []), `<div class="ln row" data-sel="${i === ov.sel}">${row(r)}</div>`]);
  return `<div class="ov" data-overlay="${ov.kind}"><div class="ln q"><i class="g">›</i><span class="tx">${esc(ov.query)}<b class="cur"> </b>${ov.query ? '' : `<span class="hint">${hint}</span>`}</span><span class="mt">${results.length}</span></div><div class="res">${rows.join('') || ln('note dim', '', empty)}</div></div>`;
}
const palette = S => central(S, 'ação, plugin ou comando do Cadente', r => `<i class="g">${r.kind === 'cap' ? '/' : r.kind === 'plugin' ? '→' : '·'}</i><span class="tx">${esc(r.label)}</span><span class="mt">${r.kind === 'host' ? kbd(r.action, S) : r.kind === 'cap' ? `<span class="mt-dim">prévia · ${esc(r.module)}</span>` : `<span class="mt-dim">${esc(plugin(r.plugin).glyph)}</span>`}</span>`);
const agents = S => central(S, 'agentes e atividade · ↵ vai até a folha', r => `${sg(r)}<span class="tx">${esc(r.label)}</span><span class="mt">${esc(r.keys)}</span>`, 'nada rodando agora · claude ou codex num Terminal');
const help = S => central(S, 'filtrar atalhos · ↵ executa · esc fecha', r => `<i class="g">·</i><span class="tx">${esc(r.label)}</span><span class="mt"><span class="kbd">${esc(r.keys)}</span></span>`);

export function render(S) {
  const tab = activeTab(S), focusedId = focused(S).id;
  const labels = S.overlay?.kind === 'jump' ? jumpLabels(S) : [];
  const r = rects(tab.tree), topLeft = Object.keys(r).find(id => r[id].x === 0 && r[id].y === 0);
  const ctx = { focusedId, labels, topLeft, multi: tab.tree.kind !== 'leaf' && !S.zoom };
  const body = S.zoom ? pane(S, findLeaf(S, S.zoom).leaf, { ...ctx, inset: !S.ui.sidebar }) : tree(S, tab.tree, ctx);
  const ov = S.overlay?.kind, marker = ov && !['palette', 'help', 'agents'].includes(ov) ? ` data-overlay="${ov}"` : '';
  const zen = S.ui.sidebar ? '' : `<span class="tl float"><i></i><i></i><i></i></span><div class="zbar">${statusLines(S).map(t => `<span>${esc(t)}</span>`).join('')}</div>`;
  return `<div class="win${S.ui.sidebar ? '' : ' zen'}"${marker}>${S.ui.sidebar ? sidebar(S, labels) : ''}<main class="tree">${body}</main>${zen}${ov === 'palette' ? palette(S) : ov === 'help' ? help(S) : ov === 'agents' ? agents(S) : ov === 'notice' ? notice(S) : ''}</div>`;
}
